from __future__ import annotations
SCHEMA_SQL=r'''PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS checklist_company_refs(id INTEGER PRIMARY KEY AUTOINCREMENT,host_company_key TEXT NOT NULL UNIQUE,ticker TEXT NOT NULL,exchange TEXT NOT NULL DEFAULT 'UNKNOWN',company_name TEXT NOT NULL,industry_name TEXT,company_type TEXT NOT NULL DEFAULT 'normal',currency TEXT NOT NULL DEFAULT 'VND',is_active INTEGER NOT NULL DEFAULT 1,host_metadata_json TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS ix_checklist_company_ticker ON checklist_company_refs(ticker,exchange);
CREATE TABLE IF NOT EXISTS checklist_questions(question_id TEXT PRIMARY KEY,question_no INTEGER NOT NULL UNIQUE CHECK(question_no BETWEEN 1 AND 59),group_name TEXT NOT NULL,question_vi TEXT NOT NULL,guidance TEXT NOT NULL,research_mode TEXT NOT NULL CHECK(research_mode IN('manual','hybrid')),supporting_tool TEXT,source_basis TEXT NOT NULL DEFAULT 'Michael Shearn - The Investment Checklist',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS screening_criteria(criterion_code TEXT PRIMARY KEY,criterion_name_en TEXT NOT NULL,criterion_name_vi TEXT NOT NULL,display_order INTEGER NOT NULL UNIQUE,source_basis TEXT NOT NULL DEFAULT 'The Investment Checklist - Table 1.1');
CREATE TABLE IF NOT EXISTS research_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_type TEXT NOT NULL DEFAULT 'full' CHECK(review_type IN('full','delta','screening')),as_of_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'in_progress' CHECK(status IN('draft','in_progress','completed','archived')),prior_review_id INTEGER REFERENCES research_reviews(id),analyst_user_id TEXT,review_reason TEXT,finalize_reason TEXT,completed_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS ix_reviews_company_date ON research_reviews(company_ref_id,as_of_date DESC,id DESC);
CREATE TABLE IF NOT EXISTS analyst_assessments(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),question_id TEXT NOT NULL REFERENCES checklist_questions(question_id),version_no INTEGER NOT NULL,analyst_answer TEXT,assessment INTEGER CHECK(assessment BETWEEN -2 AND 2),confidence INTEGER CHECK(confidence BETWEEN 1 AND 5),materiality INTEGER CHECK(materiality BETWEEN 1 AND 5),status TEXT NOT NULL CHECK(status IN('answered','research_gap','needs_review','na','not_reviewed')),change_reason TEXT,analyst_confirmed INTEGER NOT NULL DEFAULT 0,copied_from_assessment_id INTEGER REFERENCES analyst_assessments(id),created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(review_id,question_id,version_no));
CREATE TABLE IF NOT EXISTS research_sources(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),source_type TEXT NOT NULL CHECK(source_type IN('annual_report','quarterly_report','filing','investor_presentation','earnings_call','company_website','regulator','industry_report','news','interview','customer_supplier_employee','analyst_upload','other')),title TEXT NOT NULL,publisher TEXT,url TEXT,document_date TEXT,accessed_at TEXT,reliability INTEGER NOT NULL CHECK(reliability BETWEEN 1 AND 5),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','archived')),notes TEXT,source_hash TEXT NOT NULL,created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(company_ref_id,source_hash));
CREATE INDEX IF NOT EXISTS ix_research_sources_company_date ON research_sources(company_ref_id,document_date DESC,id DESC);
CREATE TABLE IF NOT EXISTS research_source_contents(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),source_id INTEGER NOT NULL REFERENCES research_sources(id),version_no INTEGER NOT NULL,content_type TEXT NOT NULL,locator_scheme TEXT NOT NULL,original_filename TEXT,scope_label TEXT,content_text TEXT NOT NULL,content_hash TEXT NOT NULL,char_count INTEGER NOT NULL CHECK(char_count>0),created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(source_id,version_no),UNIQUE(source_id,content_hash));
CREATE INDEX IF NOT EXISTS ix_source_contents_source_version ON research_source_contents(source_id,version_no DESC,id DESC);
CREATE INDEX IF NOT EXISTS ix_source_contents_company ON research_source_contents(company_ref_id,id DESC);
CREATE TABLE IF NOT EXISTS research_evidence(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),source_id INTEGER NOT NULL REFERENCES research_sources(id),evidence_key TEXT NOT NULL,version_no INTEGER NOT NULL,evidence_type TEXT NOT NULL CHECK(evidence_type IN('fact','quote','metric','observation','contradiction','risk')),locator_text TEXT,excerpt TEXT NOT NULL,analyst_note TEXT,evidence_date TEXT,verification_status TEXT NOT NULL DEFAULT 'unverified' CHECK(verification_status IN('unverified','verified','disputed','stale')),direction TEXT NOT NULL DEFAULT 'context' CHECK(direction IN('supports','contradicts','context')),confidence INTEGER NOT NULL CHECK(confidence BETWEEN 1 AND 5),change_reason TEXT,supersedes_evidence_id INTEGER REFERENCES research_evidence(id),content_hash TEXT NOT NULL,created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(source_id,evidence_key,version_no));
CREATE INDEX IF NOT EXISTS ix_research_evidence_source_key ON research_evidence(source_id,evidence_key,version_no DESC);
CREATE INDEX IF NOT EXISTS ix_research_evidence_company_date ON research_evidence(company_ref_id,evidence_date DESC,id DESC);
CREATE TABLE IF NOT EXISTS evidence_question_links(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),question_id TEXT NOT NULL REFERENCES checklist_questions(question_id),evidence_id INTEGER NOT NULL REFERENCES research_evidence(id),relationship TEXT NOT NULL CHECK(relationship IN('primary','supporting','context','contradicts')),materiality INTEGER NOT NULL CHECK(materiality BETWEEN 1 AND 5),link_note TEXT,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),deactivation_reason TEXT,created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),deactivated_at TEXT,UNIQUE(review_id,question_id,evidence_id));
CREATE INDEX IF NOT EXISTS ix_evidence_links_review_question ON evidence_question_links(review_id,question_id,is_active);
CREATE TABLE IF NOT EXISTS ai_research_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),run_type TEXT NOT NULL CHECK(run_type IN('evidence_extraction','research_gap','contradiction_scan','delta_review')),status TEXT NOT NULL DEFAULT 'completed' CHECK(status IN('completed','failed')),provider TEXT NOT NULL,model_name TEXT NOT NULL,model_version TEXT,prompt_version TEXT NOT NULL,prompt_hash TEXT NOT NULL,source_manifest_json TEXT NOT NULL,source_manifest_hash TEXT NOT NULL,input_hash TEXT NOT NULL,output_hash TEXT NOT NULL,provider_request_id TEXT,provider_response_id TEXT,client_request_id TEXT,input_tokens INTEGER,output_tokens INTEGER,total_tokens INTEGER,latency_ms INTEGER,attempt_count INTEGER,service_tier TEXT,requested_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),completed_at TEXT NOT NULL DEFAULT(datetime('now')),error_text TEXT);
CREATE INDEX IF NOT EXISTS ix_ai_runs_review_created ON ai_research_runs(review_id,id DESC);
CREATE INDEX IF NOT EXISTS ix_ai_runs_company ON ai_research_runs(company_ref_id);
CREATE TABLE IF NOT EXISTS ai_research_suggestions(id INTEGER PRIMARY KEY AUTOINCREMENT,run_id INTEGER NOT NULL REFERENCES ai_research_runs(id),company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),suggestion_no INTEGER NOT NULL,suggestion_type TEXT NOT NULL CHECK(suggestion_type IN('evidence_candidate','contradiction','research_gap')),source_id INTEGER REFERENCES research_sources(id),source_hash_at_run TEXT,source_content_id INTEGER REFERENCES research_source_contents(id),source_content_hash_at_run TEXT,question_id TEXT NOT NULL REFERENCES checklist_questions(question_id),evidence_type TEXT CHECK(evidence_type IN('fact','quote','metric','observation','contradiction','risk')),relationship TEXT CHECK(relationship IN('primary','supporting','context','contradicts')),direction TEXT CHECK(direction IN('supports','contradicts','context')),locator_text TEXT,excerpt TEXT,rationale TEXT NOT NULL,confidence INTEGER NOT NULL CHECK(confidence BETWEEN 1 AND 5),materiality INTEGER NOT NULL CHECK(materiality BETWEEN 1 AND 5),payload_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(run_id,suggestion_no));
CREATE INDEX IF NOT EXISTS ix_ai_suggestions_review_question ON ai_research_suggestions(review_id,question_id,id DESC);
CREATE INDEX IF NOT EXISTS ix_ai_suggestions_company ON ai_research_suggestions(company_ref_id);
CREATE INDEX IF NOT EXISTS ix_ai_suggestions_source ON ai_research_suggestions(source_id);
CREATE INDEX IF NOT EXISTS ix_ai_suggestions_question ON ai_research_suggestions(question_id);
CREATE TABLE IF NOT EXISTS ai_suggestion_decisions(id INTEGER PRIMARY KEY AUTOINCREMENT,suggestion_id INTEGER NOT NULL UNIQUE REFERENCES ai_research_suggestions(id),decision TEXT NOT NULL CHECK(decision IN('accepted','rejected')),decision_reason TEXT NOT NULL,created_evidence_id INTEGER REFERENCES research_evidence(id),created_link_id INTEGER REFERENCES evidence_question_links(id),decided_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS ix_ai_decisions_created ON ai_suggestion_decisions(created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS ix_ai_decisions_evidence ON ai_suggestion_decisions(created_evidence_id);
CREATE INDEX IF NOT EXISTS ix_ai_decisions_link ON ai_suggestion_decisions(created_link_id);
CREATE TABLE IF NOT EXISTS screening_assessments(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),criterion_code TEXT NOT NULL REFERENCES screening_criteria(criterion_code),version_no INTEGER NOT NULL,analyst_value TEXT NOT NULL CHECK(analyst_value IN('yes','no','unknown','na')),confidence INTEGER CHECK(confidence BETWEEN 1 AND 5),note TEXT,copied_from_screening_id INTEGER REFERENCES screening_assessments(id),analyst_confirmed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(review_id,criterion_code,version_no));
CREATE TABLE IF NOT EXISTS opportunity_inventory_snapshots(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),as_of_date TEXT NOT NULL,version_no INTEGER NOT NULL,data_origin TEXT NOT NULL DEFAULT 'manual' CHECK(data_origin IN('manual','host_data_layer','mixed')),source_as_of_date TEXT,tev REAL,ebit REAL,ebitda REAL,normalized_earnings REAL,total_debt REAL,interest_expense REAL,fcf_current REAL,market_cap REAL,dividend_per_share REAL,market_price REAL,fcf_estimate REAL,target_price REAL,ccc_days REAL,tev_ebit REAL,tev_ebitda REAL,tev_normalized_earnings REAL,pretax_earnings_yield REAL,debt_ebitda REAL,ebit_interest REAL,fcf_yield_ev REAL,fcf_yield_market REAL,dividend_yield REAL,price_vs_target REAL,quality_tally INTEGER,checklist_answered INTEGER,research_completion REAL,critical_unknowns INTEGER,red_flags INTEGER,mos REAL,thesis_direction TEXT CHECK(thesis_direction IN('up','flat','down','unknown')),last_review_id INTEGER REFERENCES research_reviews(id),note TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(company_ref_id,as_of_date,version_no));
CREATE TABLE IF NOT EXISTS data_snapshots(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER REFERENCES research_reviews(id),as_of_date TEXT NOT NULL,snapshot_type TEXT NOT NULL CHECK(snapshot_type IN('review','manual_backup')),snapshot_version INTEGER NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(review_id,snapshot_type,snapshot_version));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER REFERENCES checklist_company_refs(id),review_id INTEGER REFERENCES research_reviews(id),actor TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,before_json TEXT,after_json TEXT,correlation_id TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS integration_sync_log(id INTEGER PRIMARY KEY AUTOINCREMENT,company_ref_id INTEGER REFERENCES checklist_company_refs(id),source_module TEXT NOT NULL,source_as_of_date TEXT,payload_hash TEXT,status TEXT NOT NULL CHECK(status IN('success','partial','failed','skipped')),detail TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS peer_comparison_snapshots(company_ref_id INTEGER NOT NULL REFERENCES checklist_company_refs(id),review_id INTEGER NOT NULL REFERENCES research_reviews(id),version_no INTEGER NOT NULL,as_of_date TEXT NOT NULL,base_ticker TEXT NOT NULL,target_mos_pct REAL,peer_count INTEGER NOT NULL CHECK(peer_count BETWEEN 2 AND 10),source_module TEXT NOT NULL,payload_json TEXT NOT NULL,payload_hash TEXT NOT NULL,save_reason TEXT NOT NULL,created_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(company_ref_id,review_id,version_no));
CREATE INDEX IF NOT EXISTS ix_peer_snapshots_review ON peer_comparison_snapshots(review_id,version_no);
CREATE INDEX IF NOT EXISTS ix_peer_snapshots_company_date ON peer_comparison_snapshots(company_ref_id,as_of_date,version_no);
'''
